 "code": "def clean_title(text):
    if not text:
        return ""

    text = text.strip()
    text = text.lower()

    cleaned_text = ""
    for word in text.split():
        if word.isdigit():
            cleaned_text += word
        elif word.isalnum() or word in "-\\"":
            cleaned_text += word
        elif word == "":
            cleaned_text += ""
        else:
            cleaned_text += ""

    return cleaned_text"
